      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" font-size=\"36\" fill=\"#ffd700\" text-anchor=\"middle\" font-family=\"Arial\">Like Repel, Opposite Attract</text><text x=\"550\" y=\"100\" font-size=\"23\" fill=\"#888\" text-anchor=\"middle\" font-family=\"Arial\">The two rules of electric force</text><circle cx=\"300\" cy=\"290\" r=\"60\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"4\"/><text x=\"300\" y=\"305\" font-size=\"40\" fill=\"#f59e0b\" text-anchor=\"middle\" font-family=\"Arial\">+</text><circle cx=\"620\" cy=\"290\" r=\"60\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"4\"/><text x=\"620\" y=\"305\" font-size=\"40\" fill=\"#f59e0b\" text-anchor=\"middle\" font-family=\"Arial\">+</text><path d=\"M 380 290 L 250 290\" stroke=\"#ef4444\" stroke-width=\"5\" marker-end=\"url(#a)\"/><path d=\"M 540 290 L 670 290\" stroke=\"#ef4444\" stroke-width=\"5\" marker-end=\"url(#a)\"/><text x=\"850\" y=\"300\" font-size=\"24\" fill=\"#ef4444\" text-anchor=\"middle\" font-family=\"Arial\">REPEL</text><circle cx=\"300\" cy=\"620\" r=\"60\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"4\"/><text x=\"300\" y=\"635\" font-size=\"40\" fill=\"#f59e0b\" text-anchor=\"middle\" font-family=\"Arial\">+</text><circle cx=\"620\" cy=\"620\" r=\"60\" fill=\"rgba(99,102,241,0.15)\" stroke=\"#6366f1\" stroke-width=\"4\"/><text x=\"620\" y=\"642\" font-size=\"40\" fill=\"#6366f1\" text-anchor=\"middle\" font-family=\"Arial\">-</text><path d=\"M 380 620 L 500 620\" stroke=\"#10b981\" stroke-width=\"5\" marker-end=\"url(#b)\"/><path d=\"M 540 620 L 420 620\" stroke=\"#10b981\" stroke-width=\"5\" marker-end=\"url(#b)\"/><text x=\"850\" y=\"630\" font-size=\"24\" fill=\"#10b981\" text-anchor=\"middle\" font-family=\"Arial\">ATTRACT</text><defs><marker id=\"a\" markerWidth=\"10\" markerHeight=\"10\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#ef4444\"/></marker><marker id=\"b\" markerWidth=\"10\" markerHeight=\"10\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#10b981\"/></marker></defs><text x=\"550\" y=\"870\" font-size=\"22\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"Arial\">Same signs push apart</text><text x=\"550\" y=\"915\" font-size=\"22\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"Arial\">Different signs pull together</text></svg>",
