      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">CHECK: CAPACITANCE</text><text x=\"550\" y=\"100\" text-anchor=\"middle\" fill=\"#888\" font-size=\"23\">Solve C = Q / V</text><rect x=\"120\" y=\"200\" width=\"380\" height=\"200\" rx=\"16\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"3\"/><text x=\"310\" y=\"260\" text-anchor=\"middle\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"26\">GIVEN</text><text x=\"310\" y=\"320\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"24\">Q = 0.02 coulombs</text><text x=\"310\" y=\"365\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"24\">V = 10 volts</text><rect x=\"600\" y=\"200\" width=\"380\" height=\"200\" rx=\"16\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"3\"/><text x=\"790\" y=\"260\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"26\">FORMULA</text><text x=\"790\" y=\"330\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"32\">C = Q / V</text><path d=\"M550 420 L550 500\" stroke=\"#10b981\" stroke-width=\"5\"/><polygon points=\"550,510 538,485 562,485\" fill=\"#10b981\"/><rect x=\"260\" y=\"530\" width=\"580\" height=\"180\" rx=\"18\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"3\"/><text x=\"550\" y=\"595\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"26\">C = 0.02 / 10</text><rect x=\"330\" y=\"620\" width=\"440\" height=\"70\" rx=\"10\" fill=\"rgba(255,215,0,0.15)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"667\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"28\">C = 0.002 F</text><rect x=\"200\" y=\"760\" width=\"700\" height=\"160\" rx=\"18\" fill=\"rgba(139,92,246,0.1)\" stroke=\"#8b5cf6\" stroke-width=\"3\"/><text x=\"550\" y=\"815\" text-anchor=\"middle\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"26\">= 2000 microfarads</text><text x=\"550\" y=\"865\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"21\">The farad is huge — real parts</text><text x=\"550\" y=\"898\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"21\">are rated in uF or pF</text></svg>"
